import { renderFromConfig, ComponentRenderConfig } from './config-renderer';
import { RenderFn } from './index';

function createRenderer(config: ComponentRenderConfig): RenderFn {
  return (g, params, meta, graph) => renderFromConfig(config, g, params, meta, graph);
}

